<section class="w-full space-y-6"><div><flux:heading size="xl">{{ __('Payroll & Salary') }}</flux:heading><flux:text>{{ __('Generate attendance-adjusted monthly payroll and manage payment status.') }}</flux:text></div><flux:card><div class="grid items-end gap-4 sm:grid-cols-3"><flux:select wire:model="month" :label="__('Month')">@foreach(range(1,12) as $number)<flux:select.option :value="$number">{{ date('F', mktime(0,0,0,$number,1)) }}</flux:select.option>@endforeach</flux:select><flux:input wire:model="year" type="number" min="2000" max="2100" :label="__('Year')"/><flux:button variant="primary" wire:click="generate">{{ __('Generate payroll') }}</flux:button></div></flux:card>@foreach($this->payrolls as $payroll)<flux:card wire:key="payroll-{{ $payroll->id }}" class="space-y-4"><div class="flex justify-between"><div><flux:heading>{{ $payroll->periodLabel() }}</flux:heading><flux:text>{{ $payroll->employee_count }} {{ __('employees') }} · ৳{{ number_format((float)$payroll->total_net,2) }}</flux:text></div><flux:badge :color="$payroll->status->color()">{{ $payroll->status->label() }}</flux:badge></div><div class="divide-y divide-zinc-200 dark:divide-zinc-700">@foreach($payroll->payslips as $payslip)<div class="flex items-center justify-between gap-3 py-2"><span>{{ $payslip->employee_name }} — ৳{{ number_format((float)$payslip->net_payable,2) }}</span>@if(!$payslip->isPaid())<flux:button size="sm" wire:click="markPaid({{ $payslip->id }})">{{ __('Mark paid') }}</flux:button>@else<flux:badge color="lime">{{ __('Paid') }}</flux:badge>@endif</div>@endforeach</div></flux:card>@endforeach</section>
